/* ============================================================
   Design tokens
   ============================================================ */
:root {
  --color-brand:        #1a1a2e;
  --color-brand-mid:    #16213e;
  --color-accent:       #e94560;
  --color-accent-hover: #c73652;
  --color-gold:         #f5a623;
  --color-gold-dark:    #d4891a;
  --color-surface:      #ffffff;
  --color-surface-alt:  #f7f7fb;
  --color-border:       #e2e2ec;
  --color-text:         #1a1a2e;
  --color-text-muted:   #6b6b80;
  --color-text-inverse: #ffffff;
  --color-badge-new:    #00b894;
  --color-badge-sale:   #e94560;
  --color-badge-limited:#9b59b6;

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  16px;
  --radius-xl:  24px;
  --radius-pill:9999px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,.08);
  --shadow-md:  0 4px 16px rgba(0,0,0,.10);
  --shadow-lg:  0 8px 32px rgba(0,0,0,.14);
  --shadow-focus: 0 0 0 3px rgba(233,69,96,.45);
  --shadow-focus-light: 0 0 0 3px rgba(255,255,255,.55);

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  --transition: 180ms ease;
  --transition-slow: 320ms ease;

  --max-width: 1280px;
  --gutter: clamp(1rem, 4vw, 2rem);
}

/* ============================================================
   Reset & base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-surface);
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font: inherit; border: none; background: none; }

/* ============================================================
   Skip link
   ============================================================ */
.skip-link {
  position: absolute;
  top: -100%;
  left: var(--gutter);
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: var(--color-text-inverse);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  font-weight: 600;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; outline: 3px solid var(--color-text-inverse); outline-offset: 2px; }

/* ============================================================
   Utility
   ============================================================ */
.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
.container {
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--gutter);
}
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  color: var(--color-brand);
}
.section-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  padding: .25rem .5rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
}
.section-link:hover { color: var(--color-accent-hover); background: rgba(233,69,96,.07); }
.section-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* ============================================================
   Announcement bar
   ============================================================ */
.announcement-bar {
  background: var(--color-brand);
  color: var(--color-text-inverse);
  text-align: center;
  padding: .5rem var(--gutter);
  font-size: .8125rem;
  font-weight: 500;
  letter-spacing: .02em;
}
.announcement-bar a {
  color: var(--color-gold);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.announcement-bar a:focus-visible { outline: 2px solid var(--color-gold); outline-offset: 2px; }

/* ============================================================
   Header
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  padding-block: .875rem;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-brand);
  flex-shrink: 0;
}
.site-logo:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; border-radius: var(--radius-sm); }
.logo-mark {
  width: 36px; height: 36px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 1rem;
}

/* Primary nav */
.primary-nav { display: flex; align-items: center; justify-content: center; gap: .25rem; }
.nav-link {
  padding: .5rem .75rem;
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.nav-link:hover { color: var(--color-accent); background: rgba(233,69,96,.06); }
.nav-link[aria-current="page"] { color: var(--color-accent); }
.nav-link[aria-current="page"]::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: .75rem; right: .75rem;
  height: 2px;
  background: var(--color-accent);
  border-radius: var(--radius-pill);
}
.nav-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; }
.icon-btn {
  width: 40px; height: 40px;
  display: grid; place-items: center;
  border-radius: var(--radius-md);
  color: var(--color-text);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover { color: var(--color-accent); background: rgba(233,69,96,.07); }
.icon-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.icon-btn svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  width: 18px; height: 18px;
  background: var(--color-accent);
  color: #fff;
  font-size: .6875rem;
  font-weight: 700;
  border-radius: var(--radius-pill);
  display: grid;
  place-items: center;
  line-height: 1;
}

/* Search bar (expanded) */
.search-form {
  display: flex;
  align-items: center;
  background: var(--color-surface-alt);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-pill);
  padding: .3rem .3rem .3rem .9rem;
  transition: border-color var(--transition), box-shadow var(--transition);
  width: min(340px, 100%);
}
.search-form:focus-within {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(233,69,96,.18);
}
.search-input {
  flex: 1;
  border: none;
  background: transparent;
  font: inherit;
  font-size: .9375rem;
  color: var(--color-text);
  outline: none;
  min-width: 0;
}
.search-input::placeholder { color: var(--color-text-muted); }
.search-btn {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-pill);
  flex-shrink: 0;
  transition: background var(--transition);
}
.search-btn:hover { background: var(--color-accent-hover); }
.search-btn:focus-visible { outline: 2px solid var(--color-brand); outline-offset: 2px; }
.search-btn svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ============================================================
   Hero
   ============================================================ */
.hero {
  background: linear-gradient(135deg, var(--color-brand) 0%, var(--color-brand-mid) 60%, #0f3460 100%);
  color: var(--color-text-inverse);
  overflow: hidden;
  position: relative;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 3rem;
  min-height: 520px;
  padding-block: 4rem;
}
.hero-eyebrow {
  display: inline-block;
  background: rgba(245,166,35,.18);
  color: var(--color-gold);
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  padding: .3rem .75rem;
  border-radius: var(--radius-pill);
  margin-bottom: 1.25rem;
  border: 1px solid rgba(245,166,35,.35);
}
.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.15;
  margin-bottom: 1.25rem;
}
.hero-title em { font-style: normal; color: var(--color-accent); }
.hero-desc {
  font-size: clamp(.9375rem, 1.5vw, 1.125rem);
  color: rgba(255,255,255,.78);
  margin-bottom: 2rem;
  max-width: 42ch;
}
.hero-cta-group { display: flex; gap: .75rem; flex-wrap: wrap; }
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.625rem;
  border-radius: var(--radius-pill);
  font-size: .9375rem;
  font-weight: 600;
  transition: background var(--transition), color var(--transition), box-shadow var(--transition), transform 80ms ease;
  cursor: pointer;
}
.btn:active { transform: scale(.97); }
.btn:focus-visible { outline: 3px solid var(--color-gold); outline-offset: 3px; }
.btn-primary {
  background: var(--color-accent);
  color: #fff;
}
.btn-primary:hover { background: var(--color-accent-hover); box-shadow: 0 4px 18px rgba(233,69,96,.45); }
.btn-outline {
  background: transparent;
  color: #fff;
  border: 2px solid rgba(255,255,255,.5);
}
.btn-outline:hover { background: rgba(255,255,255,.1); border-color: #fff; }
.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}
.hero-card-stack {
  position: relative;
  width: 320px;
  height: 400px;
}
.hero-product-card {
  position: absolute;
  background: rgba(255,255,255,.08);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: var(--radius-xl);
  padding: 1.5rem;
  color: #fff;
}
.hero-product-card--main {
  width: 280px;
  top: 0; left: 0;
  z-index: 2;
}
.hero-product-card--back {
  width: 260px;
  top: 30px; left: 40px;
  z-index: 1;
  opacity: .55;
  transform: rotate(4deg);
}
.hero-product-img {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, rgba(255,255,255,.15), rgba(255,255,255,.05));
  display: grid;
  place-items: center;
  font-size: 4rem;
  margin-bottom: 1rem;
}
.hero-product-name { font-weight: 600; font-size: 1rem; margin-bottom: .25rem; }
.hero-product-price { color: var(--color-gold); font-weight: 700; font-size: 1.125rem; }
.hero-badge {
  position: absolute;
  top: -10px; right: -10px;
  background: var(--color-accent);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  padding: .35rem .7rem;
  border-radius: var(--radius-pill);
  box-shadow: var(--shadow-md);
}
.hero-dots {
  position: absolute;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: .5rem;
}
.hero-dot {
  width: 8px; height: 8px;
  border-radius: var(--radius-pill);
  background: rgba(255,255,255,.35);
  border: none;
  padding: 0;
  transition: background var(--transition), width var(--transition);
  cursor: pointer;
}
.hero-dot[aria-selected="true"] { background: #fff; width: 24px; }
.hero-dot:focus-visible { outline: 2px solid var(--color-gold); outline-offset: 3px; }

/* ============================================================
   Category strip
   ============================================================ */
.categories-section {
  padding-block: 3rem;
  background: var(--color-surface-alt);
  border-bottom: 1px solid var(--color-border);
}
.categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 1rem;
}
.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .75rem;
  padding: 1.25rem .75rem;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
  color: var(--color-text);
  text-align: center;
  font-weight: 600;
  font-size: .875rem;
}
.category-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
  color: var(--color-accent);
}
.category-card:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.category-icon {
  width: 52px; height: 52px;
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  font-size: 1.625rem;
  transition: background var(--transition);
}

/* ============================================================
   Featured products
   ============================================================ */
.products-section { padding-block: 4rem; }
.products-filter {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}
.filter-btn {
  padding: .45rem 1rem;
  border-radius: var(--radius-pill);
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  border: 1.5px solid var(--color-border);
  background: transparent;
  transition: all var(--transition);
}
.filter-btn:hover { border-color: var(--color-accent); color: var(--color-accent); }
.filter-btn[aria-pressed="true"] {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}
.filter-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

/* Product card */
.product-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: rgba(233,69,96,.25);
}
.product-card:focus-within { border-color: var(--color-accent); }
.product-img-wrap {
  position: relative;
  background: var(--color-surface-alt);
  aspect-ratio: 1;
  overflow: hidden;
  display: grid;
  place-items: center;
  font-size: 5rem;
}
.product-img-bg {
  position: absolute;
  inset: 0;
  transition: transform var(--transition-slow);
}
.product-card:hover .product-img-bg { transform: scale(1.06); }
.product-emoji {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 8px 16px rgba(0,0,0,.12));
  transition: transform var(--transition-slow);
}
.product-card:hover .product-emoji { transform: scale(1.08) translateY(-4px); }
.product-badges {
  position: absolute;
  top: .75rem; left: .75rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
  z-index: 2;
}
.badge {
  display: inline-block;
  padding: .2rem .6rem;
  border-radius: var(--radius-pill);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.badge--new   { background: var(--color-badge-new); color: #fff; }
.badge--sale  { background: var(--color-badge-sale); color: #fff; }
.badge--limited { background: var(--color-badge-limited); color: #fff; }
.product-wishlist {
  position: absolute;
  top: .75rem; right: .75rem;
  width: 36px; height: 36px;
  background: var(--color-surface);
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow: var(--shadow-sm);
  z-index: 2;
  transition: background var(--transition), color var(--transition);
  color: var(--color-text-muted);
}
.product-wishlist:hover { background: var(--color-accent); color: #fff; }
.product-wishlist:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.product-wishlist[aria-pressed="true"] { color: var(--color-accent); }
.product-wishlist[aria-pressed="true"]:hover { color: #fff; }
.product-wishlist svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; }
.product-wishlist[aria-pressed="true"] svg { fill: currentColor; }
.product-body {
  padding: 1.125rem;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  flex: 1;
}
.product-category {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: .06em;
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.35;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .8125rem;
}
.stars { color: var(--color-gold); letter-spacing: .05em; }
.rating-count { color: var(--color-text-muted); }
.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5rem;
  margin-top: auto;
  padding-top: .75rem;
  border-top: 1px solid var(--color-border);
}
.price-wrap { display: flex; align-items: baseline; gap: .4rem; }
.price-current {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-brand);
}
.price-original {
  font-size: .875rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.price-save {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-accent);
}
.add-to-cart {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  padding: .55rem 1rem;
  background: var(--color-brand);
  color: #fff;
  border-radius: var(--radius-pill);
  font-size: .875rem;
  font-weight: 600;
  transition: background var(--transition), box-shadow var(--transition);
  white-space: nowrap;
}
.add-to-cart:hover { background: var(--color-accent); box-shadow: 0 4px 12px rgba(233,69,96,.35); }
.add-to-cart:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.add-to-cart svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; }

/* ============================================================
   Deals section
   ============================================================ */
.deals-section {
  padding-block: 4rem;
  background: var(--color-surface-alt);
}
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}
.deal-card {
  border-radius: var(--radius-xl);
  overflow: hidden;
  position: relative;
  min-height: 280px;
  display: flex;
  align-items: flex-end;
  color: #fff;
  transition: box-shadow var(--transition), transform var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }
.deal-card:focus-within { outline: 2px solid var(--color-accent); outline-offset: 3px; }
.deal-card--featured {
  grid-row: span 2;
  min-height: 0;
  align-items: stretch;
  flex-direction: column;
}
.deal-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.deal-bg--1 { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); }
.deal-bg--2 { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }
.deal-bg--3 { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); }
.deal-bg--4 { background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%); }
.deal-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.65) 0%, rgba(0,0,0,.1) 60%);
  z-index: 1;
}
.deal-emoji {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%,-60%);
  font-size: 6rem;
  z-index: 1;
  filter: drop-shadow(0 8px 24px rgba(0,0,0,.25));
  pointer-events: none;
}
.deal-card--featured .deal-emoji { top: 35%; font-size: 7rem; }
.deal-content {
  position: relative;
  z-index: 2;
  padding: 1.5rem;
  width: 100%;
}
.deal-tag {
  display: inline-block;
  background: var(--color-accent);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  padding: .25rem .65rem;
  border-radius: var(--radius-pill);
  margin-bottom: .75rem;
}
.deal-title {
  font-family: var(--font-display);
  font-size: clamp(1.25rem, 2.5vw, 1.625rem);
  font-weight: 700;
  margin-bottom: .5rem;
  line-height: 1.2;
}
.deal-desc { font-size: .875rem; opacity: .85; margin-bottom: 1rem; }
.deal-link {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  font-size: .875rem;
  font-weight: 700;
  color: #fff;
  background: rgba(255,255,255,.2);
  padding: .5rem 1.125rem;
  border-radius: var(--radius-pill);
  border: 1.5px solid rgba(255,255,255,.45);
  backdrop-filter: blur(6px);
  transition: background var(--transition), border-color var(--transition);
}
.deal-link:hover { background: rgba(255,255,255,.3); border-color: rgba(255,255,255,.8); }
.deal-link:focus-visible { outline: 3px solid #fff; outline-offset: 3px; }
.deal-countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}
.countdown-unit {
  background: rgba(255,255,255,.18);
  backdrop-filter: blur(6px);
  border-radius: var(--radius-md);
  padding: .4rem .7rem;
  text-align: center;
  min-width: 52px;
}
.countdown-num {
  display: block;
  font-size: 1.5rem;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.countdown-label { font-size: .65rem; text-transform: uppercase; letter-spacing: .08em; opacity: .75; }

/* ============================================================
   Trust bar
   ============================================================ */
.trust-section {
  padding-block: 2.5rem;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}
.trust-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1.5rem;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.trust-icon {
  width: 48px; height: 48px;
  background: rgba(233,69,96,.1);
  color: var(--color-accent);
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.trust-icon svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.trust-title { font-weight: 700; font-size: .9375rem; margin-bottom: .1rem; }
.trust-desc { font-size: .8125rem; color: var(--color-text-muted); }

/* ============================================================
   Editorial / Blog
   ============================================================ */
.editorial-section { padding-block: 4rem; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}
.editorial-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
  display: flex;
  flex-direction: column;
}
.editorial-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: rgba(233,69,96,.25);
}
.editorial-card:focus-within { border-color: var(--color-accent); }
.editorial-img {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #667eea, #764ba2);
  display: grid;
  place-items: center;
  font-size: 4rem;
  overflow: hidden;
  position: relative;
}
.editorial-img-bg {
  position: absolute;
  inset: 0;
  transition: transform var(--transition-slow);
}
.editorial-card:hover .editorial-img-bg { transform: scale(1.06); }
.editorial-img-emoji {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 12px rgba(0,0,0,.2));
}
.editorial-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; gap: .5rem; }
.editorial-meta {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .75rem;
  color: var(--color-text-muted);
}
.editorial-tag {
  display: inline-block;
  background: rgba(233,69,96,.1);
  color: var(--color-accent);
  font-weight: 700;
  font-size: .7rem;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: .2rem .55rem;
  border-radius: var(--radius-pill);
}
.editorial-title {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-brand);
}
.editorial-link {
  display: block;
  color: inherit;
}
.editorial-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; border-radius: var(--radius-sm); }
.editorial-excerpt {
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}
.read-more {
  margin-top: auto;
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  padding: .1rem 0;
  border-radius: var(--radius-sm);
  transition: gap var(--transition);
}
.read-more:hover { gap: .5rem; }
.read-more:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* ============================================================
   Newsletter
   ============================================================ */
.newsletter-section {
  padding-block: 4rem;
  background: linear-gradient(135deg, var(--color-brand) 0%, #0f3460 100%);
  color: #fff;
  text-align: center;
}
.newsletter-inner { max-width: 600px; margin-inline: auto; }
.newsletter-eyebrow {
  display: inline-block;
  background: rgba(245,166,35,.18);
  color: var(--color-gold);
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  padding: .3rem .75rem;
  border-radius: var(--radius-pill);
  margin-bottom: 1.25rem;
  border: 1px solid rgba(245,166,35,.35);
}
.newsletter-title {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 700;
  margin-bottom: .75rem;
}
.newsletter-desc {
  font-size: 1rem;
  opacity: .78;
  margin-bottom: 2rem;
}
.newsletter-form {
  display: flex;
  gap: .5rem;
  max-width: 480px;
  margin-inline: auto;
}
.newsletter-input {
  flex: 1;
  padding: .75rem 1.25rem;
  border: 2px solid rgba(255,255,255,.25);
  border-radius: var(--radius-pill);
  background: rgba(255,255,255,.1);
  color: #fff;
  font: inherit;
  font-size: .9375rem;
  backdrop-filter: blur(6px);
  transition: border-color var(--transition), box-shadow var(--transition);
  min-width: 0;
}
.newsletter-input::placeholder { color: rgba(255,255,255,.5); }
.newsletter-input:focus {
  outline: none;
  border-color: var(--color-gold);
  box-shadow: 0 0 0 3px rgba(245,166,35,.3);
}
.newsletter-btn {
  padding: .75rem 1.625rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-pill);
  font: inherit;
  font-size: .9375rem;
  font-weight: 700;
  white-space: nowrap;
  transition: background var(--transition), box-shadow var(--transition);
}
.newsletter-btn:hover { background: var(--color-accent-hover); box-shadow: 0 4px 18px rgba(233,69,96,.5); }
.newsletter-btn:focus-visible { outline: 3px solid var(--color-gold); outline-offset: 3px; }
.newsletter-note {
  margin-top: 1rem;
  font-size: .8125rem;
  opacity: .6;
}
.newsletter-success {
  display: none;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-gold);
}

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--color-brand);
  color: rgba(255,255,255,.75);
  padding-top: 4rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,.1);
}
.footer-brand-desc {
  font-size: .9375rem;
  line-height: 1.7;
  margin-block: 1rem;
  opacity: .75;
}
.footer-social {
  display: flex;
  gap: .5rem;
  margin-top: 1.25rem;
}
.social-btn {
  width: 38px; height: 38px;
  border-radius: var(--radius-md);
  background: rgba(255,255,255,.1);
  display: grid;
  place-items: center;
  color: rgba(255,255,255,.75);
  transition: background var(--transition), color var(--transition);
  font-size: .875rem;
  font-weight: 700;
}
.social-btn:hover { background: var(--color-accent); color: #fff; }
.social-btn:focus-visible { outline: 2px solid var(--color-gold); outline-offset: 2px; }
.footer-heading {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 1.25rem;
}
.footer-links { display: flex; flex-direction: column; gap: .6rem; }
.footer-link {
  font-size: .875rem;
  color: rgba(255,255,255,.6);
  transition: color var(--transition);
}
.footer-link:hover { color: #fff; }
.footer-link:focus-visible { outline: 2px solid var(--color-gold); outline-offset: 2px; border-radius: var(--radius-sm); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 1.5rem;
  font-size: .8125rem;
  flex-wrap: wrap;
}
.footer-legal {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

/* ============================================================
   Live region
   ============================================================ */
.cart-live-region {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  pointer-events: none;
}
.cart-toast {
  background: var(--color-brand);
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-lg);
  font-size: .875rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  border-left: 4px solid var(--color-accent);
  opacity: 0;
  transform: translateY(12px);
  transition: opacity var(--transition), transform var(--transition);
  pointer-events: auto;
}
.cart-toast.visible { opacity: 1; transform: translateY(0); }

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .header-inner { grid-template-columns: auto auto; }
  .primary-nav { display: none; }
  .primary-nav.is-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0; right: 0;
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    padding: 1rem var(--gutter);
    box-shadow: var(--shadow-md);
    align-items: flex-start;
    z-index: 99;
  }
  .search-form { display: none; }
  .menu-toggle { display: grid; }
  .hero-inner { grid-template-columns: 1fr; text-align: center; }
  .hero-desc { margin-inline: auto; }
  .hero-cta-group { justify-content: center; }
  .hero-visual { display: none; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--featured { grid-row: span 1; }
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-form { flex-direction: column; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

/* ============================================================
   Focus visible (browsers without :focus-visible support)
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

/* ============================================================
   Forced colors
   ============================================================ */
@media (forced-colors: active) {
  .btn-primary, .add-to-cart, .newsletter-btn, .search-btn {
    background: ButtonText;
    color: ButtonFace;
    border: 2px solid ButtonBorder;
  }
  .product-card, .deal-card, .editorial-card, .category-card {
    border: 2px solid ButtonBorder;
  }
  .badge { background: Highlight; color: HighlightText; }
  .icon-btn:focus-visible,
  .nav-link:focus-visible,
  .filter-btn:focus-visible,
  .add-to-cart:focus-visible {
    outline: 3px solid ButtonText;
  }
  .hero-dot[aria-selected="true"] { background: ButtonText; }
  .deal-overlay { display: none; }
  .deal-card { color: CanvasText; background: Canvas; }
}

