  place-items: center;
  line-height: 1;
}

/* Search bar (expanded) */
.search-form {
  display: flex;
  align-items: center;
  background: var(--color-surface-alt);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-pill);
