  border-radius: var(--radius-pill);
  margin-bottom: 1.25rem;
  border: 1px solid rgba(245,166,35,.35);
}
.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 700;
