}
.hero-product-card--back {
  width: 260px;
  top: 30px; left: 40px;
  z-index: 1;
  opacity: .55;
  transform: rotate(4deg);
}
.hero-product-img {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, rgba(255,255,255,.15), rgba(255,255,255,.05));
  display: grid;
  place-items: center;
  font-size: 4rem;
  margin-bottom: 1rem;
}
.hero-product-name { font-weight: 600; font-size: 1rem; margin-bottom: .25rem; }
.hero-product-price { color: var(--color-gold); font-weight: 700; font-size: 1.125rem; }
.hero-badge {
  position: absolute;
  top: -10px; right: -10px;
  background: var(--color-accent);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  padding: .35rem .7rem;
  border-radius: var(--radius-pill);
  box-shadow: var(--shadow-md);
}
.hero-dots {
  position: absolute;
  bottom: 2rem;
