.hero-dot:focus-visible { outline: 2px solid var(--color-gold); outline-offset: 3px; }

/* ============================================================
   Category strip
   ============================================================ */
.categories-section {
  padding-block: 3rem;
  background: var(--color-surface-alt);
  border-bottom: 1px solid var(--color-border);
