+}
+.countdown-num {
+  display: block;
+  font-size: 1.5rem;
+  font-weight: 800;
+  line-height: 1;
+  font-variant-numeric: tabular-nums;
+}
+.countdown-label { font-size: .65rem; text-transform: uppercase; letter-spacing: .08em; opacity: .75; }
+
+/* ============================================================
+   Trust bar
+   ============================================================ */
+.trust-section {
+  padding-block: 2.5rem;
+  border-top: 1px solid var(--color-border);
+  border-bottom: 1px solid var(--color-border);
+}
+.trust-list {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
+  gap: 1.5rem;
+}
+.trust-item {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+.trust-icon {
+  width: 48px; height: 48px;
+  background: rgba(233,69,96,.1);
+  color: var(--color-accent);
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+  flex-shrink: 0;
+}
+.trust-icon svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
+.trust-title { font-weight: 700; font-size: .9375rem; margin-bottom: .1rem; }
+.trust-desc { font-size: .8125rem; color: var(--color-text-muted); }
+
+/* ============================================================
+   Editorial / Blog
+   ============================================================ */
+.editorial-section { padding-block: 4rem; }
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr 1fr;
+  gap: 1.5rem;
+}
+.editorial-card {
+  border-radius: var(--radius-lg);
