          card.hidden = !show;
        });
      });
    });
  }

  /* ----------------------------------------------------------
     Wishlist toggle
  ---------------------------------------------------------- */
  $$('.product-wishlist').forEach((btn) => {
    btn.addEventListener('click', () => {
      const pressed = btn.getAttribute('aria-pressed') === 'true';
      btn.setAttribute('aria-pressed', String(!pressed));
      const label = btn.querySelector('.wishlist-label');
      if (label) {
        label.textContent = pressed ? 'Add to wishlist' : 'Remove from wishlist';
      }
    });
  });

  /* ----------------------------------------------------------
     Cart counter & toast notification
  ---------------------------------------------------------- */
  let cartCount = 3;
  const cartCountEl = $('#cart-count');
  const liveRegion = $('#cart-live');

  function showToast(message) {
    if (!liveRegion) return;
    const toast = document.createElement('div');
    toast.className = 'cart-toast';
    toast.textContent = message;
    toast.setAttribute('role', 'status');
    liveRegion.appendChild(toast);

