import re

class LintCheck(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.ids = []
        self.labels = []
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        id_ = d.get('id')
        if id_:
            if id_ in self.ids:
                self.errors.append(f'Duplicate id: {id_}')
