const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');

// Check duplicate IDs
const ids = [...html.matchAll(/id=[\"']([\w-]+)[\"']/g)].map(m=>m[1]);
const counts = {};
ids.forEach(id => counts[id] = (counts[id]||0)+1);
const dupes = Object.entries(counts).filter(([k,v])=>v>1);
console.log('Duplicate IDs:', dupes.length ? dupes.map(d=>d[0]).join(', ') : 'None');
console.log('Total IDs:', ids.length);

// Check aria-labelledby refs
const idSet = new Set(ids);
const ariaRefs = [...html.matchAll(/aria-labelledby=[\"']([\w -]+)[\"']/g)];
ariaRefs.forEach(m => {
  m[1].split(/\s+/).forEach(ref => {
    if (!idSet.has(ref)) console.log('MISSING aria-labelledby target:', ref);
  });
});

// Check for= refs
const forRefs = [...html.matchAll(/\bfor=[\"']([\w-]+)[\"']/g)];
forRefs.forEach(m => {
  if (!idSet.has(m[1])) console.log('MISSING label target:', m[1]);
});

// Check aria-controls
const ctrlRefs = [...html.matchAll(/aria-controls=[\"']([\w-]+)[\"']/g)];
ctrlRefs.forEach(m => {
  if (!idSet.has(m[1])) console.log('MISSING aria-controls target:', m[1]);
});

console.log('All references validated.');
"
